// Rules, no LLM: turn the article HTML into clean text + outbound link candidates.
// Falls back to the RSS text if the page can't be fetched.
const src = $('When called by orchestrator').item.json;
let html = typeof $json.html === 'string' ? $json.html : '';
const flags = [];
const decode = s => s.replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&quot;/g, '"')
  .replace(/&#8217;|&rsquo;/g, "'").replace(/&#8216;|&lsquo;/g, "'").replace(/&#8220;|&#8221;|&ldquo;|&rdquo;/g, '"')
  .replace(/&#8211;|&ndash;/g, '-').replace(/&#8212;|&mdash;/g, '-').replace(/&euro;/g, '€').replace(/&pound;/g, '£')
  .replace(/&#(\d+);/g, (m, n) => String.fromCharCode(+n)).replace(/&[a-z]+;/gi, ' ');
let body = '';
if (html.length > 500) {
  html = html.replace(/<(script|style|noscript|svg|nav|header|footer|aside|form)[\s\S]*?<\/\1>/gi, ' ');
  const art = html.match(/<article[\s\S]*?<\/article>/i);
  body = art ? art[0] : (html.match(/<body[\s\S]*<\/body>/i) || [html])[0];
} else flags.push('Article fetch failed');
const srcHost = (() => { try { return new URL(src.link).hostname.replace(/^www\./, ''); } catch (e) { return ''; } })();
const SKIP = /(linkedin|twitter|x\.com|facebook|instagram|youtube|crunchbase|dealroom|google|apple|wordpress|gravatar|tech\.eu|eu-startups|mailchimp|bit\.ly|t\.co|medium|substack|wikipedia|tiktok|spotify|cookiebot|onetrust)/i;
const links = [...body.matchAll(/href="(https?:\/\/[^"#?]+)/gi)].map(m => m[1])
  .map(u => { try { return new URL(u).hostname.replace(/^www\./, '').toLowerCase(); } catch (e) { return null; } })
  .filter(h => h && h !== srcHost && !SKIP.test(h));
const text = body ? decode(body.replace(/<br\s*\/?>/gi, ' ').replace(/<\/p>/gi, ' \n').replace(/<[^>]+>/g, ' ')).replace(/\s+/g, ' ').trim() : '';
const full = text.length > 400 ? text.slice(0, 9000) : src.text;
if (text && text.length <= 400) flags.push('Article fetch failed');
return { json: { ...src, rssText: src.text, text: full, linkHosts: [...new Set(links)].slice(0, 25), prepFlags: flags } };

// Rule-based pre-check BEFORE any LLM call. Hits never reach the model.
const PATTERNS = [
  /ignore (all |any )?(previous|prior|above|earlier) (instructions|prompts?)/i,
  /disregard (the )?(previous|above|system)/i,
  /you are now/i, /act as (an? )?(ai|assistant|chatgpt)/i,
  /system (prompt|message|note)/i, /\bassistant\s*:/i,
  /(set|give|rate|score)\b.{0,30}\b(icp|score|points?)\b.{0,15}\b(3|three|maximum|highest)/i,
  /ignoriere (alle |die )?(vorherigen|bisherigen) (anweisungen|instruktionen)/i,
  /systemhinweis|ki-assistent|bewerte dieses unternehmen/i
];
const hay = `${$json.title} ${$json.text}`;
const hit = PATTERNS.find(p => p.test(hay));
return { json: { ...$json, injection: !!hit, injectionPattern: hit ? String(hit) : null } };

